    interactiveSetByUser: options.interactiveSetByUser===true, isInteractiveEnv, yes: options.yes },
  buildDefaultDecisionDeps(),
);
```
- 文件 src/main.ts：commander upgrade 子命令加 .option("--interactive",...) / .option("--no-interactive",...)，解析出 interactive 与 interactiveSetByUser（commander 对 --no-xxx 有内置处理，注意区分"未指定"与"显式 false"）。

═══════════════════════════════════
第 5 步：backup/copy/prune 改为按 decision 执行
═══════════════════════════════════
文件 src/commands/upgrade.ts：
- 第7步备份（约154-162行）：用 decision.backup 替代从 plan.modified/plan.removed 构造的 backupSet：
```ts
const backupEntries = Array.from(decision.backup).map(relPath => ({ relPath }));
let backupResult;
if (backupEntries.length > 0) backupResult = await createBackup(target, backupEntries, "before-upgrade");
```
- 第8步 copy（约170-182行）：includes 循环的 filter 增加 decision 过滤：
```ts
filter: (_abs, rel) => {
  const targetRel = inc.targetSubPath ? `${inc.targetSubPath}/${rel}` : rel;
  if (isCodegraph && (rel==="node_modules"||rel==="package-lock.json")) return false;
  if (decision.keep.has(targetRel)) return false;
  if (decision.editResults.some(e => e.relPath===targetRel)) return false; // 由 8.5 写回
  return true;
}
```
- 新增 step8.5（copy 之后、prune 之前）：写回 editResults：
```ts
for (const ed of decision.editResults) {
  const abs = join(target, ed.relPath);
  ensureDir(dirname(abs));   // fs-safe 已有 ensureDir
  // 用临时文件+rename 原子写（若无 atomicWriteFile 就内联实现：写 .tmp 再 renameSync）
  await fs.promises.writeFile(abs, ed.content, "utf-8");
  logger.info(`wrote edited ${ed.relPath}${ed.matchesTheirs ? " (matches new version — merged)" : " (user edit kept)"}`);
}
```
  注意：检查 src/lib/fs-safe.ts 是否已有 atomicWriteFile/ensureDir；没有就用 fs.promises.writeFile。dirname 从 node:path 引入。
