  mode: StrategyMode;
}

/** Inputs the caller must supply to drive a decision. */
export interface DecisionInput {
  plan: DiffPlan;
  includes: PkgInclude[];
  /**
   * The install target root. Required so the default adapter can read
   * `current` content for `edit` decisions. Decision.ts itself never reads
   * files; this field is forwarded to the adapter via `deps`.
   */
  target: string;
  /**
   * Override for the asset root (defaults to `<pkg>/assets`). Forwarded to
   * the default adapter so it can resolve `new` content paths for `edit`.
   */
  assetsRoot?: string;
  prune: boolean;
  /**
   * Whether the caller (commander) wants to enter the interactive loop at
   * all. Combined with `isInteractiveEnv` and `yes` to decide whether any
   * prompt is fired.
   */
  interactive: boolean;
  /**
   * True when the user explicitly passed `--interactive` or `--no-interactive`.
   * Used so we can decide whether a non-interactive run was a deliberate
   * "I want batch behaviour" choice vs. a fallback from missing tty.
   */
  interactiveSetByUser: boolean;
  /** TTY + non-CI check from env.isInteractive(). */
  isInteractiveEnv: boolean;
  /** True when -y / --yes was passed; always suppresses prompts. */
  yes?: boolean;
}

/**
 * Test seam — every prompt, renderer, editor, env lookup, and hash function
 * is injectable. Production code calls `buildDefaultDecisionDeps()` from
 * `decision-defaults.ts`; tests pass fakes that record calls and return
 * scripted answers.
 */
export interface DecisionDeps {
  promptStrategy?: () => Promise<StrategyMode>;
  promptFileDecision?: (
    entry: PlanEntry,
    remaining: number,
    kind: FileKind,
  ) => Promise<FileDecision | "__adopt-all" | "__keep-all">;
  renderUnifiedDiff?: (relPath: string, fromAbs: string, toAbs: string) => Promise<string>;
  /**
   * Open an editor on the user's copy of `relPath` and return the merged
   * content. The default adapter in `decision-defaults.ts` reads
   * `currentContent` from `<target>/<relPath>` and `newContent` from
   * `<assetsRoot>/<relPath>` itself; the empty-string sentinels from
   * `decision.ts` are placeholders the adapter ignores.
   */
  openEditor?: (relPath: string, currentContent: string, newContent: string) => Promise<string>;
  env?: NodeJS.ProcessEnv;
  sha256Content?: (content: string) => string;
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

/** Find the include that owns a target-relative path. */
function findInclude(includes: PkgInclude[], relPath: string): PkgInclude | undefined {
  // Match from longest targetSubPath first so ".pi/extensions/codegraph" wins
  // over ".pi" if both were ever registered. We don't currently do that, but
  // the sort makes the lookup robust against future changes.
  const sorted = [...includes].sort(
    (a, b) => b.targetSubPath.length - a.targetSubPath.length,
  );
  for (const inc of sorted) {
    if (!inc.targetSubPath) return inc;
    if (relPath === inc.targetSubPath) return inc;
    if (relPath.startsWith(`${inc.targetSubPath}/`)) return inc;
  }
  return undefined;
}

/**
 * Build the PlanEntry list from a DiffPlan + includes, flagging each entry
 * with the owning include's `interactive` setting.
 *
 * The diff's `fromHash` / `toHash` are preserved as-is so the decision layer
 * can reason about whether a file even exists on disk (removed) or in assets
 * (added).
 */
function entriesFromPlan(plan: DiffPlan, includes: PkgInclude[]): PlanEntry[] {
  const entries: PlanEntry[] = [];
  for (const m of plan.modified) {
    const inc = findInclude(includes, m.relPath);
    entries.push({
      relPath: m.relPath,
      kind: "modified",
      fromHash: m.fromHash,
      toHash: m.toHash,
      interactive: inc?.interactive === true,
    });
  }
  for (const a of plan.added) {
    const inc = findInclude(includes, a.relPath);
    entries.push({
      relPath: a.relPath,
      kind: "added",
      toHash: a.toHash,
      interactive: inc?.interactive === true,
    });
  }
  for (const r of plan.removed) {
    const inc = findInclude(includes, r.relPath);
    entries.push({
      relPath: r.relPath,
      kind: "removed",
      fromHash: r.fromHash,
      interactive: inc?.interactive === true,
    });
  }
  // Keep the same order plan.modified/added/removed are sorted in (by relPath
  // alphabetically within each bucket) so per-file prompts are deterministic.
  return entries;
}

/**
 * Decide whether we should prompt the user at all. Two paths land in
 * "no prompts → all-adopt default":
 *
 *   1. Non-interactive environment (no tty / CI / PISQUAD_NO_TTY).
 *   2. Caller opted out: `--no-interactive` or `--yes`.
 *
 * If the user did NOT explicitly opt out (`interactiveSetByUser === false`)
 * AND we have no tty, we still run a non-interactive pass so the command
 * works in CI — but we leave the door open to log a heads-up via the
 * upgrade command's logger.
 */
function shouldPrompt(input: DecisionInput): boolean {
  if (input.yes === true) return false;
  if (input.interactive === false) return false;
  if (!input.isInteractiveEnv) return false;
  return true;
}

/**
 * Compute the upgrade's action plan.
 *
 * The function is intentionally free of side effects beyond the supplied
 * `deps`. It does NOT read files, spawn editors, or write anything. Real I/O
 * is funnelled through `deps` so tests can drive every branch deterministically.
 */
export async function resolveUpgradeActions(
  input: DecisionInput,
  deps: DecisionDeps = {},
): Promise<ResolvedPlan> {
  const sha256Content = deps.sha256Content ?? defaultSha256Content;

  const empty: ResolvedPlan = {
    entries: new Map(),
    adopt: new Set(),
    keep: new Set(),
    remove: new Set(),
    backup: new Set(),
    editResults: [],
    mode: "all-adopt",
  };

  const allEntries = entriesFromPlan(input.plan, input.includes);
  if (allEntries.length === 0) return empty;

  const interactiveEntries = allEntries.filter((e) => e.interactive);
  const managedEntries = allEntries.filter((e) => !e.interactive);

  // 1. Managed (non-interactive) entries follow the legacy behaviour: modified
  //    overwrites (the legacy code path also backs them up), added copies, and
  //    removed is kept unless --prune is in play. None of these depend on the
  //    user-facing prompts, so we resolve them up front.
  for (const entry of managedEntries) {
    switch (entry.kind) {
      case "modified":
        empty.adopt.add(entry.relPath);
        empty.backup.add(entry.relPath);
        break;
      case "added":
        empty.adopt.add(entry.relPath);
        break;
      case "removed":
        if (input.prune) {
          empty.remove.add(entry.relPath);
          empty.backup.add(entry.relPath);
        } else {
          empty.keep.add(entry.relPath);
        }
        break;
    }
  }

  // 2. If there are no interactive entries, we're done. This is the common
  //    case for projects that only have extension-channel updates, and it
  //    keeps the upgrade behaviour identical to the pre-interactive version.
  if (interactiveEntries.length === 0) return empty;

  // 3. Decide the strategy. When we cannot prompt, default to all-adopt — that
  //    matches the legacy "no-tty → batch overwrite" behaviour and is also the
  //    command's documented non-interactive fallback.
  let mode: StrategyMode;
  if (!shouldPrompt(input)) {
    mode = "all-adopt";
  } else if (deps.promptStrategy === undefined) {
    // Should not happen in practice (the default deps always supply it), but
    // guard so the function is safe to call with `deps = {}`.
    mode = "all-adopt";
  } else {
    mode = await deps.promptStrategy();
  }
  empty.mode = mode;

  // 4. Apply the strategy to interactive entries.
  if (mode === "all-adopt") {
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          empty.backup.add(entry.relPath);
          break;
        case "added":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          break;
        case "removed":
          empty.entries.set(entry.relPath, "keep");
          empty.keep.add(entry.relPath);
          break;
      }
    }
    return empty;
  }

  if (mode === "all-keep") {
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
        case "added":
        case "removed":
          empty.entries.set(entry.relPath, "keep");
          empty.keep.add(entry.relPath);
          break;
      }
    }
    return empty;
  }

  // 5. per-file: walk the entries in deterministic order, ask the user, and
  //    honour batch shortcuts that fan out to remaining entries.
  if (deps.promptFileDecision === undefined || deps.openEditor === undefined) {
    // Same fallback as above — if the caller asked for per-file but didn't
    // wire the prompt functions, we degrade to all-adopt rather than throw.
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          empty.backup.add(entry.relPath);
          break;
        case "added":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          break;
        case "removed":
          empty.entries.set(entry.relPath, "keep");
          empty.keep.add(entry.relPath);
          break;
      }
    }
    return empty;
  }

  // Walk the interactive entries; track remaining = how many entries the user
  // has not yet seen, so batch shortcuts can advertise "Adopt all remaining
  // (N)". Index-based loop because we break out via the batch shortcuts.
  for (let i = 0; i < interactiveEntries.length; i++) {
    const entry = interactiveEntries[i]!;
    const remaining = interactiveEntries.length - i - 1;
    const answer = await deps.promptFileDecision(entry, remaining, entry.kind);
    if (answer === "__adopt-all" || answer === "__keep-all") {
      // Resolve the current entry with the batch decision, then fill the rest.
      const decision: FileDecision = answer === "__adopt-all" ? "adopt" : "keep";
      await applyInteractiveDecision(empty, entry, decision, deps, sha256Content);
      for (let j = i + 1; j < interactiveEntries.length; j++) {
        await applyInteractiveDecision(
          empty,
          interactiveEntries[j]!,
          decision,
          deps,
          sha256Content,
        );
      }
      return empty;
    }
    await applyInteractiveDecision(empty, entry, answer, deps, sha256Content);
  }
  return empty;
}

/** Apply a single per-file decision to the in-progress plan. */
async function applyInteractiveDecision(
  plan: ResolvedPlan,
  entry: PlanEntry,
  decision: FileDecision,
  deps: DecisionDeps,
  sha256Content: (content: string) => string,
): Promise<void> {
  plan.entries.set(entry.relPath, decision);
  if (decision === "keep") {
    plan.keep.add(entry.relPath);
    return;
  }
  if (decision === "adopt") {
    plan.adopt.add(entry.relPath);
    if (entry.kind === "modified" || entry.kind === "removed") {
      plan.backup.add(entry.relPath);
    }
    return;
  }
  // decision === "edit": invoke the editor via deps. openEditor is guaranteed
  // to exist here because the caller only enters per-file mode when it does.
  // (resolveUpgradeActions short-circuits to all-adopt otherwise.)
  const openEditor = deps.openEditor!;
  // currentContent / newContent are filled by the default adapter; tests can
  // supply a stub that ignores them and returns a canned string.
  const edited = await openEditor(entry.relPath, "", "");
  if (edited.length === 0) {
    // Empty editor result → treat as "keep my version". Surface this via
    // entries map (already set) and skip backup; the file is left alone.
    plan.keep.add(entry.relPath);
    return;
  }
  const matchesTheirs = typeof entry.toHash === "string" && sha256Content(edited) === entry.toHash;
  plan.editResults.push({ relPath: entry.relPath, content: edited, matchesTheirs });
  plan.backup.add(entry.relPath);
}

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expand, editor } from "@inquirer/prompts";
import { execCapture, which } from "../lib/env.js";
import { logger } from "../lib/logger.js";
import type {
  DecisionDeps,
  FileKind,
  PlanEntry,
  StrategyMode,
} from "./decision.js";

/**
 * Default `DecisionDeps` for production use.
 *
 * Wires the real @inquirer/prompts `expand` and `editor` prompts plus the
 * `diff` CLI (with a read-and-print fallback when `diff` is not installed)
 * into the dependency-injected decision layer. Tests bypass this module
 * entirely and construct fake `DecisionDeps` to drive every branch.
 *
 * `target` and `assetsRoot` are stashed on the returned object so the
 * `openEditor` adapter can resolve absolute paths for the file it streams
 * into the editor. They are intentionally NOT used by `promptStrategy` or
 * `promptFileDecision` — those only need to know the per-file entry.
 */
export function buildDefaultDecisionDeps(
  target: string,
  assetsRoot: string,
): DecisionDeps {
  return {
    promptStrategy: defaultPromptStrategy,
    promptFileDecision: defaultPromptFileDecision,
    renderUnifiedDiff: defaultRenderUnifiedDiff,
    openEditor: (relPath: string) => defaultOpenEditor(relPath, target, assetsRoot),
    sha256Content: defaultSha256Content,
  };
}

/**
 * Top-level strategy picker: batch-adopt (default), batch-keep, or per-file.
 *
 * Uses the @inquirer/prompts `expand` widget so the user picks a single
 * letter rather than navigating an arrow list. The legacy `default` key
 * (`1`) makes "Adopt new" the highlighted choice when the user just hits
 * enter — matching the documented behaviour for the non-interactive
 * fallback.
 */
async function defaultPromptStrategy(): Promise<StrategyMode> {
  const result = await expand({
    message: "Choose upgrade strategy for interactive files",
    default: "1",
    choices: [
      { key: "1", name: "Adopt new version for every file (recommended)", value: "all-adopt" },
      { key: "2", name: "Keep my current files (skip all updates)", value: "all-keep" },
      { key: "3", name: "Decide per file", value: "per-file" },
    ],
  });
  if (result === "all-adopt" || result === "all-keep" || result === "per-file") return result;
  // Defensive: should never happen given the choices above.
  return "all-adopt";
}

/**
 * Per-file decision prompt. The choices vary by `kind` because the user's
 * mental model is different for an existing-but-modified file vs. a brand
 * new file vs. one slated for deletion under --prune.
 *
 * When `remaining > 0` we append two batch shortcuts:
 *
 *   - `r` (Adopt all remaining N) — collapse every subsequent file to adopt.
 *   - `t` (Keep all remaining N) — collapse every subsequent file to keep.
 *
 * The sentinel values `__adopt-all` / `__keep-all` are recognised by
 * `resolveUpgradeActions` to fan the decision out and exit the per-file loop.
 */
async function defaultPromptFileDecision(
  entry: PlanEntry,
  remaining: number,
  kind: FileKind,
): Promise<"adopt" | "keep" | "edit" | "__adopt-all" | "__keep-all"> {
  const header = describeEntry(entry);
  const baseChoices =
    kind === "modified"
      ? [
          { key: "a", name: "Adopt new version", value: "adopt" as const },
          { key: "k", name: "Keep my version", value: "keep" as const },
          { key: "e", name: "Edit / merge manually in $EDITOR", value: "edit" as const },
        ]
      : kind === "added"
        ? [
            { key: "a", name: "Adopt new file", value: "adopt" as const },
            { key: "k", name: "Skip (don't add this file)", value: "keep" as const },
          ]
        : [
            { key: "a", name: "Delete (--prune)", value: "adopt" as const },
            { key: "k", name: "Keep my file", value: "keep" as const },
          ];

  const batchChoices: Array<{ key: "r" | "t"; name: string; value: "__adopt-all" | "__keep-all" }> =
    remaining > 0
      ? [
          {
            key: "r",
            name: `Adopt all remaining (${remaining})`,
            value: "__adopt-all",
          },
          {
            key: "t",
            name: `Keep all remaining (${remaining})`,
            value: "__keep-all",
          },
        ]
      : [];

  const answer = await expand({
    message: header,
    default: kind === "modified" ? "k" : "a",
    choices: [...baseChoices, ...batchChoices],
  });
  if (answer === "__adopt-all" || answer === "__keep-all") return answer;
  if (answer === "adopt" || answer === "keep" || answer === "edit") return answer;
  // Defensive: fall back to keep if the prompt somehow returns an unknown value.
  return "keep";
}

function describeEntry(entry: PlanEntry): string {
  const verb = entry.kind === "modified" ? "modified" : entry.kind === "added" ? "added" : "removed";
  return `${entry.relPath} (${verb})`;
}

/**
 * Render a unified diff for the file. Uses the system `diff` CLI when
 * available; otherwise prints the new version's full content under a clear
 * header so the user can still review what would land.
 *
 * Returns the rendered string (also printed to the upgrade log) so callers
 * that want to keep the diff around — e.g. for a `--diff-out` flag — can
 * consume it without re-running `diff`.
 */
async function defaultRenderUnifiedDiff(
  relPath: string,
  fromAbs: string,
  toAbs: string,
): Promise<string> {
  logger.info(`--- unified diff for ${relPath} ---`);
  if (which("diff") !== null) {
    const result = await execCapture("diff", ["-u", fromAbs, toAbs]);
    const stdout = result.stdout.trim();
    if (stdout.length === 0) {
      logger.info("(files are identical)");
      return "";
    }
    for (const line of stdout.split(/\r?\n/)) logger.info(line);
    if (result.exitCode > 1) {
      // diff exits 1 when files differ — expected. > 1 means actual error.
      logger.warn(`diff exited ${result.exitCode}: ${result.stderr.trim()}`);
    }
    return stdout;
  }
  // Fallback: print the new version in full so the user can still review.
  logger.info("(diff CLI not found; showing new version in full)");
  logger.info("New version from assets:");
  const newContent = readFileSync(toAbs, "utf-8");
  for (const line of newContent.split(/\r?\n/)) logger.info(line);
  return newContent;
}

/**
 * Open the user's editor on the current file and return whatever they
 * saved. Falls back to logging a warning and returning an empty string
 * (which `resolveUpgradeActions` treats as "keep my version") if the editor
 * is missing or exits non-zero.
 *
 * We pass `waitForUserInput: true` so the prompt does not return until the
 * user closes their editor — without this, @inquirer/editor would resolve
 * immediately with the unchanged default and the user would see nothing
 * happen.
 */
async function defaultOpenEditor(
  relPath: string,
  target: string,
  assetsRoot: string,
): Promise<string> {
  const currentPath = join(target, relPath);
  const newPath = join(assetsRoot, relPath);
  let current = "";
  try {
    current = readFileSync(currentPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read current version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  let incoming = "";
  try {
    incoming = readFileSync(newPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read new version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  logger.info(`--- editing ${relPath} ---`);
  logger.info("New version from assets:");
  for (const line of incoming.split(/\r?\n/)) logger.info(line);
  logger.info("--- end of new version; opening $EDITOR with current content as default ---");

  try {
    const edited = await editor({
      message: `Edit ${relPath} (close the editor when done; an empty file means "keep my version")`,
      default: current,
      postfix: ".md",
      waitForUserInput: true,
    });
    return edited;
  } catch (error) {
    logger.warn(
      `editor failed for ${relPath}: ${error instanceof Error ? error.message : String(error)} — keeping current version`,
    );
    return "";
  }
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

