    const userContent = "USER_OVERRIDE_" + Date.now();
    writeUserFile(target, targetFile, userContent);

    const { deps } = makeDeps("all-keep", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // For .pi/agents (interactive=true), the test set strategy=all-keep so
    // the user content survives. But for a managed entry the strategy
    // choice is irrelevant — managed is always adopted. We test that
    // elsewhere; here we just verify the file ends up matching assets.
    // The current assets file's content is whatever the seeded assets
    // contained. We just verify the user's marker is gone.
    const finalContent = readTarget(target, targetFile);
    assert.equal(finalContent.includes("USER_OVERRIDE"), false, "user override replaced");
  });

