      continue;
    }
    const answer = await deps.promptFileDecision(entry, remaining, entry.kind);
    if (answer === "__adopt-all" || answer === "__keep-all") {
      // Resolve the current entry with the batch decision, then fill the rest.
      const decision: FileDecision = answer === "__adopt-all" ? "adopt" : "keep";
      await applyInteractiveDecision(empty, entry, decision, deps, sha256Content, input.prune);
      for (let j = i + 1; j < interactiveEntries.length; j++) {
        await applyInteractiveDecision(
          empty,
          interactiveEntries[j]!,
          decision,
          deps,
          sha256Content,
          input.prune,
        );
      }
      return empty;
    }
    await applyInteractiveDecision(empty, entry, answer, deps, sha256Content, input.prune);
  }
  return empty;
}

/** Apply a single per-file decision to the in-progress plan. */
async function applyInteractiveDecision(
  plan: ResolvedPlan,
  entry: PlanEntry,
  decision: FileDecision,
  deps: DecisionDeps,
  sha256Content: (content: string) => string,
  prune: boolean,
): Promise<void> {
  plan.entries.set(entry.relPath, decision);
  if (decision === "keep") {
    plan.keep.add(entry.relPath);
    return;
  }
  if (decision === "adopt") {
    if (entry.kind === "removed") {
      // "adopt" for a removed file = "delete this file". Only honourable
      // when --prune is in play; otherwise we silently keep the user's copy
      // (the prompt defaults "Adopt" for removed entries to mean "delete",
      // so the user expects this behaviour even though their pick is
      // effectively no-op'd without --prune).
      if (prune) {
        plan.remove.add(entry.relPath);
        plan.backup.add(entry.relPath);
      } else {
        plan.keep.add(entry.relPath);
      }
      return;
    }
    plan.adopt.add(entry.relPath);
    if (entry.kind === "modified") {
      plan.backup.add(entry.relPath);
    }
    return;
  }
  // decision === "edit": invoke the editor via deps. openEditor is guaranteed
  // to exist here because the caller only enters per-file mode when it does.
  // (resolveUpgradeActions short-circuits to all-adopt otherwise.)
  const openEditor = deps.openEditor!;
  // currentContent / newContent are filled by the default adapter; tests can
  // supply a stub that ignores them and returns a canned string.
  const edited = await openEditor(entry.relPath, "", "");
  if (edited.length === 0) {
    // Empty editor result → treat as "keep my version". Surface this via
    // entries map (already set) and skip backup; the file is left alone.
    plan.keep.add(entry.relPath);
    return;
  }
  const matchesTheirs = typeof entry.toHash === "string" && sha256Content(edited) === entry.toHash;
  plan.editResults.push({ relPath: entry.relPath, content: edited, matchesTheirs });
  plan.backup.add(entry.relPath);
}

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expand, editor } from "@inquirer/prompts";
import { execCapture as defaultExecCapture, which as defaultWhich } from "../lib/env.js";
import { logger } from "../lib/logger.js";
import type {
  DecisionDeps,
  FileKind,
  PlanEntry,
  StrategyMode,
} from "./decision.js";

/**
 * Default `DecisionDeps` for production use.
 *
 * Wires the real @inquirer/prompts `expand` and `editor` prompts plus the
 * `diff` CLI (with a read-and-print fallback when `diff` is not installed)
 * into the dependency-injected decision layer. Tests bypass this module
 * entirely and construct fake `DecisionDeps` to drive every branch.
 *
 * `target` and `assetsRoot` are stashed on the returned object so the
 * `openEditor` adapter can resolve absolute paths for the file it streams
 * into the editor. They are intentionally NOT used by `promptStrategy` or
 * `promptFileDecision` — those only need to know the per-file entry.
 */
export function buildDefaultDecisionDeps(
  target: string,
  assetsRoot: string,
  overrides: BuildDefaultDecisionDepsOptions = {},
): DecisionDeps {
  const which = overrides.which ?? defaultWhich;
  const execCapture = overrides.execCapture ?? defaultExecCapture;
  return {
    promptStrategy: defaultPromptStrategy,
    promptFileDecision: defaultPromptFileDecision,
    renderUnifiedDiff: (relPath, fromAbs, toAbs) =>
      defaultRenderUnifiedDiff(relPath, fromAbs, toAbs, { which, execCapture }),
    openEditor: (relPath: string) => defaultOpenEditor(relPath, target, assetsRoot),
    sha256Content: defaultSha256Content,
  };
}

/** Optional overrides for `buildDefaultDecisionDeps`. All fields default
 * to the real implementation from `lib/env.js`. Tests use these to inject
 * stubs (e.g. simulate a missing `diff` binary). */
export interface BuildDefaultDecisionDepsOptions {
  which?: (cmd: string) => string | null;
  execCapture?: typeof defaultExecCapture;
}

/**
 * Top-level strategy picker: batch-adopt (default), batch-keep, or per-file.
 *
 * Uses the @inquirer/prompts `expand` widget so the user picks a single
 * letter rather than navigating an arrow list. The legacy `default` key
 * (`1`) makes "Adopt new" the highlighted choice when the user just hits
 * enter — matching the documented behaviour for the non-interactive
 * fallback.
 */
async function defaultPromptStrategy(): Promise<StrategyMode> {
  const result = await expand({
    message: "Choose upgrade strategy for interactive files",
    default: "1",
    choices: [
      { key: "1", name: "Adopt new version for every file (recommended)", value: "all-adopt" },
      { key: "2", name: "Keep my current files (skip all updates)", value: "all-keep" },
      { key: "3", name: "Decide per file", value: "per-file" },
    ],
  });
  if (result === "all-adopt" || result === "all-keep" || result === "per-file") return result;
  // Defensive: should never happen given the choices above.
  return "all-adopt";
}

/**
 * Per-file decision prompt. The choices vary by `kind` because the user's
 * mental model is different for an existing-but-modified file vs. a brand
 * new file vs. one slated for deletion under --prune.
 *
 * When `remaining > 0` we append two batch shortcuts:
 *
 *   - `r` (Adopt all remaining N) — collapse every subsequent file to adopt.
 *   - `t` (Keep all remaining N) — collapse every subsequent file to keep.
 *
 * The sentinel values `__adopt-all` / `__keep-all` are recognised by
 * `resolveUpgradeActions` to fan the decision out and exit the per-file loop.
 */
type FileDecisionAnswer = "adopt" | "keep" | "edit" | "__adopt-all" | "__keep-all";

async function defaultPromptFileDecision(
  entry: PlanEntry,
  remaining: number,
  kind: FileKind,
): Promise<FileDecisionAnswer> {
  const header = describeEntry(entry);
  // Track which key is the default so we can label it in the choice name.
  // inquirer's `expand` highlights the default key in the prompt UI, but
  // the choice name itself stays plain text — appending "(default)" makes
  // it explicit in non-interactive contexts (CI logs, screen readers, etc.).
  const defaultKey: "a" | "k" | "e" = kind === "modified" ? "k" : "a";
  const label = (key: "a" | "k" | "e", name: string): string =>
    key === defaultKey ? `${name} (default)` : name;
  const baseChoices: Array<{ key: "a" | "k" | "e"; name: string; value: FileDecisionAnswer }> =
    kind === "modified"
      ? [
          { key: "a", name: label("a", "Adopt new version"), value: "adopt" },
          { key: "k", name: label("k", "Keep my version"), value: "keep" },
          { key: "e", name: label("e", "Edit / merge manually in $EDITOR"), value: "edit" },
        ]
      : kind === "added"
        ? [
            { key: "a", name: label("a", "Adopt new file"), value: "adopt" },
            { key: "k", name: label("k", "Skip (don't add this file)"), value: "keep" },
          ]
        : [
            { key: "a", name: label("a", "Delete (--prune)"), value: "adopt" },
            { key: "k", name: label("k", "Keep my file"), value: "keep" },
          ];

  const batchChoices: Array<{ key: "r" | "t"; name: string; value: FileDecisionAnswer }> =
    remaining > 0
      ? [
          {
            key: "r",
            name: `Adopt all remaining (${remaining})`,
            value: "__adopt-all",
          },
          {
            key: "t",
            name: `Keep all remaining (${remaining})`,
            value: "__keep-all",
          },
        ]
      : [];

  const answer = await expand<FileDecisionAnswer>({
    message: header,
    default: defaultKey,
    choices: [...baseChoices, ...batchChoices],
  });
  if (answer === "__adopt-all" || answer === "__keep-all") return answer;
  if (answer === "adopt" || answer === "keep" || answer === "edit") return answer;
  // Defensive: fall back to keep if the prompt somehow returns an unknown value.
  return "keep";
}

function describeEntry(entry: PlanEntry): string {
  const verb = entry.kind === "modified" ? "modified" : entry.kind === "added" ? "added" : "removed";
  return `${entry.relPath} (${verb})`;
}

/**
 * Render a unified diff for the file. Uses the system `diff` CLI when
 * available; otherwise prints the new version's full content under a clear
 * header so the user can still review what would land.
 *
 * Returns the rendered string (also printed to the upgrade log) so callers
 * that want to keep the diff around — e.g. for a `--diff-out` flag — can
 * consume it without re-running `diff`.
 */
async function defaultRenderUnifiedDiff(
  relPath: string,
  fromAbs: string,
  toAbs: string,
  deps: { which: (cmd: string) => string | null; execCapture: typeof defaultExecCapture } = {
    which: defaultWhich,
    execCapture: defaultExecCapture,
  },
): Promise<string> {
  logger.info(`--- unified diff for ${relPath} ---`);
  if (deps.which("diff") !== null) {
    const result = await deps.execCapture("diff", ["-u", fromAbs, toAbs]);
    const stdout = result.stdout.trim();
    if (stdout.length === 0) {
      logger.info("(files are identical)");
      return "";
    }
    for (const line of stdout.split(/\r?\n/)) logger.info(line);
    if (result.exitCode > 1) {
      // diff exits 1 when files differ — expected. > 1 means actual error.
      logger.warn(`diff exited ${result.exitCode}: ${result.stderr.trim()}`);
    }
    return stdout;
  }
  // Fallback: print the new version in full so the user can still review.
  logger.info("(diff CLI not found; showing new version in full)");
  logger.info("New version from assets:");
  const newContent = readFileSync(toAbs, "utf-8");
  for (const line of newContent.split(/\r?\n/)) logger.info(line);
  return newContent;
}

export { defaultRenderUnifiedDiff };

/**
 * Open the user's editor on the current file and return whatever they
 * saved. Falls back to logging a warning and returning an empty string
 * (which `resolveUpgradeActions` treats as "keep my version") if the editor
 * is missing or exits non-zero.
 *
 * We pass `waitForUserInput: true` so the prompt does not return until the
 * user closes their editor — without this, @inquirer/editor would resolve
 * immediately with the unchanged default and the user would see nothing
 * happen.
 */
async function defaultOpenEditor(
  relPath: string,
  target: string,
  assetsRoot: string,
): Promise<string> {
  const currentPath = join(target, relPath);
  const newPath = join(assetsRoot, relPath);
  let current = "";
  try {
    current = readFileSync(currentPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read current version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  let incoming = "";
  try {
    incoming = readFileSync(newPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read new version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  logger.info(`--- editing ${relPath} ---`);
  logger.info("New version from assets:");
  for (const line of incoming.split(/\r?\n/)) logger.info(line);
  logger.info("--- end of new version; opening $EDITOR with current content as default ---");

  try {
    const edited = await editor({
      message: `Edit ${relPath} (close the editor when done; an empty file means "keep my version")`,
      default: current,
      postfix: ".md",
      waitForUserInput: true,
    });
    return edited;
  } catch (error) {
    logger.warn(
      `editor failed for ${relPath}: ${error instanceof Error ? error.message : String(error)} — keeping current version`,
    );
    return "";
  }
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import {
  resolveUpgradeActions,
  type DecisionDeps,
  type DecisionInput,
} from "../../src/upgrade/decision.js";
import type { DiffPlan, PkgInclude } from "../../src/lib/diff.js";

/**
 * Helper: compute a stable sha256 hex from a string (mirrors the default
 * `sha256Content` implementation but kept inline so tests don't have to
 * import from `decision.ts`).
 */
function sha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

/** Minimal deps that record calls and return scripted answers. */
interface Spy {
  deps: DecisionDeps;
  promptStrategyCalls: number;
  promptFileDecisionCalls: number;
  openEditorCalls: number;
  renderUnifiedDiffCalls: number;
}

function makeSpy(overrides: Partial<DecisionDeps> = {}): Spy {
  const spy: Spy = {
    deps: {
      promptStrategy: async () => {
        spy.promptStrategyCalls += 1;
        return "per-file";
      },
      promptFileDecision: async () => {
        spy.promptFileDecisionCalls += 1;
        return "keep";
      },
      openEditor: async () => {
        spy.openEditorCalls += 1;
        return "edited";
      },
      renderUnifiedDiff: async () => {
        spy.renderUnifiedDiffCalls += 1;
        return "";
      },
      sha256Content,
      ...overrides,
    },
    promptStrategyCalls: 0,
    promptFileDecisionCalls: 0,
    openEditorCalls: 0,
    renderUnifiedDiffCalls: 0,
  };
  // Wrap the original functions so call counts are recorded even when the
  // caller passes overrides (we want consistent accounting).
  const userPrompt = overrides.promptStrategy;
  const userFile = overrides.promptFileDecision;
  const userEditor = overrides.openEditor;
  const userDiff = overrides.renderUnifiedDiff;
  spy.deps.promptStrategy = async () => {
    spy.promptStrategyCalls += 1;
    return userPrompt ? userPrompt() : "per-file";
  };
  spy.deps.promptFileDecision = async (entry, remaining, kind) => {
    spy.promptFileDecisionCalls += 1;
    return userFile ? userFile(entry, remaining, kind) : "keep";
  };
  spy.deps.openEditor = async (relPath, current, incoming) => {
    spy.openEditorCalls += 1;
    return userEditor ? userEditor(relPath, current, incoming) : "edited";
  };
  spy.deps.renderUnifiedDiff = async (relPath, from, to) => {
    spy.renderUnifiedDiffCalls += 1;
    return userDiff ? userDiff(relPath, from, to) : "";
  };
  spy.deps.sha256Content = overrides.sha256Content ?? sha256Content;
  return spy;
}

/** Standard fixture: three interactive includes + two managed. */
const INTERACTIVE_INCLUDES: PkgInclude[] = [
  { pkgSubPath: "docs", targetSubPath: "docs", interactive: true },
  { pkgSubPath: ".pi/agents", targetSubPath: ".pi/agents", interactive: true },
  { pkgSubPath: ".pi/skills", targetSubPath: ".pi/skills", interactive: true },
];
const MANAGED_INCLUDES: PkgInclude[] = [
  { pkgSubPath: ".pi/extensions/subagent", targetSubPath: ".pi/extensions/subagent" },
  { pkgSubPath: ".pi/extensions/wikilink-lint", targetSubPath: ".pi/extensions/wikilink-lint" },
];

function planFixture(): DiffPlan {
  return {
    modified: [
      { relPath: "docs/README.md", fromHash: "h-old-1", toHash: "h-new-1" },
      { relPath: "docs/sub.md", fromHash: "h-old-2", toHash: "h-new-2" },
      { relPath: ".pi/agents/worker.md", fromHash: "h-old-3", toHash: "h-new-3" },
    ],
    added: [
      { relPath: "docs/new.md", toHash: "h-new-4" },
      { relPath: ".pi/skills/project-docs/SKILL.md", toHash: "h-new-5" },
    ],
    removed: [{ relPath: "docs/old.md", fromHash: "h-old-r1" }],
    unchanged: [],
  };
}

function baseInput(overrides: Partial<DecisionInput> = {}): DecisionInput {
  return {
    plan: planFixture(),
    includes: [...INTERACTIVE_INCLUDES, ...MANAGED_INCLUDES],
    target: "/tmp/fake-target",
    prune: false,
    interactive: true,
    interactiveSetByUser: true,
    isInteractiveEnv: true,
    yes: false,
    ...overrides,
  };
}

describe("resolveUpgradeActions", () => {
  it("all-adopt: backups 3 modified, adopts 5 (3+2), keeps 1 removed", async () => {
    const spy = makeSpy({
      promptStrategy: async () => "all-adopt",
    });
    const result = await resolveUpgradeActions(baseInput(), spy.deps);
    // Interactive: 3 modified + 2 added adopt (3 modified also backup).
    // Removed interactive: 1 file kept (since prune=false).
    assert.equal(result.adopt.size, 5, "adopt = 3 modified + 2 added");
    assert.equal(result.keep.size, 1, "keep = 1 removed (no prune)");
    assert.equal(result.remove.size, 0);
    assert.equal(result.backup.size, 3, "backup = 3 modified (interactive)");
    assert.equal(result.mode, "all-adopt");
    assert.equal(spy.promptStrategyCalls, 1);
    assert.equal(spy.promptFileDecisionCalls, 0, "no per-file prompts");
    assert.equal(spy.openEditorCalls, 0, "no editor opened");
  });

  it("all-keep: 0 adopt, all 6 in keep, 0 backup", async () => {
    const spy = makeSpy({
      promptStrategy: async () => "all-keep",
    });
    const result = await resolveUpgradeActions(baseInput(), spy.deps);
    assert.equal(result.adopt.size, 0);
    assert.equal(result.keep.size, 6, "keep = 3 modified + 2 added + 1 removed");
    assert.equal(result.remove.size, 0);
    assert.equal(result.backup.size, 0);
    assert.equal(result.mode, "all-keep");
    assert.equal(spy.promptStrategyCalls, 1);
    assert.equal(spy.promptFileDecisionCalls, 0);
  });

  it("per-file: every interactive decision = keep, all adopt+backup paths still go through managed-only", async () => {
    // Plan with only managed entries — no interactive at all.
    const managedOnlyPlan: DiffPlan = {
      modified: [
        { relPath: ".pi/extensions/subagent/index.ts", fromHash: "h-m1", toHash: "h-n1" },
      ],
      added: [],
      removed: [],
      unchanged: [],
    };
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
    });
    const result = await resolveUpgradeActions(
      baseInput({ plan: managedOnlyPlan }),
      spy.deps,
    );
    // Only managed entries — no prompt needed (managed is auto-resolve).
    assert.equal(result.adopt.size, 1);
    assert.equal(result.backup.size, 1);
    assert.equal(spy.promptStrategyCalls, 0, "no strategy prompt when there are no interactive entries");
    assert.equal(spy.promptFileDecisionCalls, 0);
  });

  it("per-file: when user picks keep for every interactive file, only modified/added go into backup if they were 'adopt'", async () => {
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      promptFileDecision: async () => "keep",
    });
    const result = await resolveUpgradeActions(baseInput(), spy.deps);
    // Interactive counts: 3 modified + 2 added + 1 removed = 6 in total.
    // Default baseInput has prune=false, so the W2 fix auto-keeps the
    // removed file without firing promptFileDecision — only 5 prompts
    // run, but all 6 files end up in the keep set.
    assert.equal(result.adopt.size, 0, "no adopt when every interactive file is kept");
    assert.equal(result.keep.size, 6, "keep = 3 modified + 2 added + 1 removed (auto)");
    assert.equal(result.backup.size, 0, "no backup when nothing is overwritten");
    // promptFileDecision is invoked for each of the 5 promptable interactive
    // entries (managed entries never reach the per-file loop, and prune=false
    // suppresses the removed prompt per the W2 fix).
    assert.equal(spy.promptFileDecisionCalls, 5);
    assert.equal(spy.openEditorCalls, 0, "no edits");
  });

  it("per-file mid-stream __adopt-all: remaining interactive files collapse to adopt", async () => {
    const answers = [
      "keep",
      "__adopt-all",
    ] as const;
    let i = 0;
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      promptFileDecision: async () => {
        const v = answers[i++] ?? "keep";
        return v as "keep" | "__adopt-all";
      },
    });
    const result = await resolveUpgradeActions(baseInput(), spy.deps);
    // First file: keep. Second file: __adopt-all → triggers batch.
    // Remaining 5 interactive files (4 left + current) all adopt.
    // Files:
    //   modified[0] = docs/README.md (interactive) → keep
    //   modified[1] = docs/sub.md (interactive) → adopt
    //   modified[2] = .pi/agents/worker.md (interactive) → adopt
    //   added[0]    = docs/new.md (interactive) → adopt
    //   added[1]    = .pi/skills/.../SKILL.md (interactive) → adopt
    //   removed[0]  = docs/old.md (interactive, prune=false) → adopt-batch... but removed
    //                  batch treats them as "keep" by default (no --prune).
    assert.equal(spy.promptFileDecisionCalls, 2, "broke out of the loop at the batch shortcut");
    // Interactive batch adopt on a `removed` file without prune = keep.
    // 4 adopted (2 modified + 2 added), 2 kept (1 modified + 1 removed).
    assert.equal(result.adopt.size, 4);
    assert.equal(result.keep.size, 2);
    assert.equal(result.backup.size, 2, "backup = 2 modified (adopted)");
  });

  it("per-file edit: openEditor called once, editResults recorded, backup includes that file", async () => {
    const editedText = "manually merged content";
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      // First modified is docs/README.md → pick "edit".
      promptFileDecision: async (_entry, remaining) => {
        if (remaining === 5) return "edit";
        return "keep";
      },
      openEditor: async () => editedText,
    });
    const result = await resolveUpgradeActions(baseInput(), spy.deps);
    assert.equal(spy.openEditorCalls, 1);
    assert.equal(result.editResults.length, 1);
    const first = result.editResults[0]!;
    assert.equal(first.relPath, "docs/README.md");
    assert.equal(first.content, editedText);
    assert.equal(first.matchesTheirs, false, "matchesTheirs false because toHash is fake");
    assert.ok(result.backup.has("docs/README.md"));
    // Note: the file is NOT in `adopt` because the copy filter will skip it
    // (the upgrade command's filter checks editResults).
    assert.equal(result.adopt.has("docs/README.md"), false);
  });

  it("non-interactive environment: no prompts at all, falls back to all-adopt", async () => {
    const spy = makeSpy();
    const result = await resolveUpgradeActions(
      baseInput({ isInteractiveEnv: false }),
      spy.deps,
    );
    assert.equal(result.mode, "all-adopt");
    assert.equal(spy.promptStrategyCalls, 0);
    assert.equal(spy.promptFileDecisionCalls, 0);
    assert.equal(spy.openEditorCalls, 0);
    // Interactive modified → adopt+backup (3), interactive added → adopt (2),
    // interactive removed (no prune) → keep (1).
    assert.equal(result.adopt.size, 5);
    assert.equal(result.keep.size, 1);
    assert.equal(result.backup.size, 3);
  });

  it("--no-interactive: explicit opt-out still triggers all-adopt default without prompts", async () => {
    const spy = makeSpy();
    const result = await resolveUpgradeActions(
      baseInput({ interactive: false, interactiveSetByUser: true }),
      spy.deps,
    );
    assert.equal(result.mode, "all-adopt");
    assert.equal(spy.promptStrategyCalls, 0);
    assert.equal(spy.promptFileDecisionCalls, 0);
    assert.equal(result.adopt.size, 5);
  });

  it("--yes: yes flag suppresses prompts even on a tty", async () => {
    const spy = makeSpy();
    const result = await resolveUpgradeActions(
      baseInput({ yes: true }),
      spy.deps,
    );
    assert.equal(result.mode, "all-adopt");
    assert.equal(spy.promptStrategyCalls, 0);
  });

  it("empty plan: returns empty ResolvedPlan without calling prompts", async () => {
    const spy = makeSpy();
    const emptyPlan: DiffPlan = { modified: [], added: [], removed: [], unchanged: [] };
    const result = await resolveUpgradeActions(
      baseInput({ plan: emptyPlan }),
      spy.deps,
    );
    assert.equal(result.adopt.size, 0);
    assert.equal(result.keep.size, 0);
    assert.equal(result.remove.size, 0);
    assert.equal(result.backup.size, 0);
    assert.equal(result.editResults.length, 0);
    assert.equal(spy.promptStrategyCalls, 0);
  });

  it("managed entries (interactive=false) are auto-resolved regardless of prompt deps", async () => {
    // Even if prompt deps would error (we throw), managed entries are
    // resolved before any prompt is fired.
    const managedPlan: DiffPlan = {
      modified: [
        { relPath: ".pi/extensions/subagent/a.ts", fromHash: "h-m1", toHash: "h-n1" },
        { relPath: ".pi/extensions/wikilink-lint/b.ts", fromHash: "h-m2", toHash: "h-n2" },
      ],
      added: [],
      removed: [],
      unchanged: [],
    };
    const spy = makeSpy();
    const result = await resolveUpgradeActions(
      baseInput({ plan: managedPlan }),
      spy.deps,
    );
    assert.equal(result.adopt.size, 2);
    assert.equal(result.backup.size, 2, "both managed modified backed up");
    // No interactive entries → no strategy prompt.
    assert.equal(spy.promptStrategyCalls, 0);
  });

  it("prune=true: removed entries are presented for prompt decision and end up in remove set when adopted", async () => {
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      // All kept — but specifically test that removed is asked.
      promptFileDecision: async () => "keep",
    });
    const result = await resolveUpgradeActions(
      baseInput({ prune: true }),
      spy.deps,
    );
    // Interactive removed (docs/old.md, no prune in plan but yes prune flag) → keep.
    assert.ok(result.keep.has("docs/old.md"));
    assert.equal(result.remove.size, 0);
    // Verify that promptFileDecision was called for the removed file.
    const removedPrompted = spy.promptFileDecisionCalls === 6; // 3 mod + 2 add + 1 rem
    assert.ok(removedPrompted, "removed file was prompted");
  });

  it("prune=true: removed adopted → goes into remove and backup", async () => {
    const answers: Array<"adopt" | "keep" | "edit" | "__adopt-all" | "__keep-all"> = ["adopt"];
    let i = 0;
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      promptFileDecision: async () => {
        return answers[i++] ?? "adopt";
      },
    });
    const result = await resolveUpgradeActions(
      baseInput({ prune: true }),
      spy.deps,
    );
    // First entry (docs/README.md, modified) → adopt+backup.
    // Subsequent batch adopt fills the rest, including removed which becomes remove+backup.
    assert.ok(result.remove.has("docs/old.md"));
    assert.ok(result.backup.has("docs/old.md"));
  });

  it("edit: empty editor result → treated as keep, no edit result, no backup", async () => {
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      promptFileDecision: async (_entry, remaining) => {
        if (remaining === 5) return "edit";
        return "keep";
      },
      openEditor: async () => "",
    });
    const result = await resolveUpgradeActions(baseInput(), spy.deps);
    assert.equal(result.editResults.length, 0);
    assert.ok(result.keep.has("docs/README.md"));
    assert.equal(result.backup.has("docs/README.md"), false);
    assert.equal(result.adopt.has("docs/README.md"), false);
  });

  it("edit: matchesTheirs=true when user saves content that hashes to toHash", async () => {
    const plan = planFixture();
    const targetContent = "whatever the user already had"; // arbitrary
    const newContent = "the new version of the file"; // arbitrary
    const newHash = sha256Content(newContent);
    // Mutate the plan so docs/README.md's toHash matches sha256 of newContent.
    const modifiedIdx = plan.modified.findIndex((m: { relPath: string }) => m.relPath === "docs/README.md")!;
    plan.modified[modifiedIdx] = { ...plan.modified[modifiedIdx]!, toHash: newHash };
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      promptFileDecision: async (_entry, remaining) => {
        if (remaining === 5) return "edit";
        return "keep";
      },
      openEditor: async () => newContent,
    });
    const result = await resolveUpgradeActions(baseInput({ plan }), spy.deps);
    assert.equal(result.editResults.length, 1);
    assert.equal(result.editResults[0]!.matchesTheirs, true);
    // ignore targetContent / unused-variable lint
    void targetContent;
  });

  it("per-file + prune=false: removed entries do not trigger promptFileDecision (auto-keep)", async () => {
    // Regression for the W2 review finding: when the user picked "Decide
    // per file" but prune is off, asking about a `removed` file would only
    // produce confusing no-ops (we can't delete without --prune). The
    // decision layer must auto-apply keep and skip the prompt entirely.
    const seenKinds: string[] = [];
    const spy = makeSpy({
      promptStrategy: async () => "per-file",
      promptFileDecision: async (_entry, _remaining, kind) => {
        seenKinds.push(kind);
        if (kind === "removed") {
          throw new Error(
            "promptFileDecision must not be called for `removed` entries when prune is false",
          );
        }
        return "keep";
      },
    });
    const result = await resolveUpgradeActions(baseInput({ prune: false }), spy.deps);
    // The single interactive `removed` file from the fixture was auto-kept.
    assert.ok(result.keep.has("docs/old.md"), "removed file auto-kept without prompt");
    assert.equal(result.remove.has("docs/old.md"), false, "not added to remove set");
    // No prompts fired for the removed entry. The other 5 interactive
    // entries (3 modified + 2 added) are also queried — they all fall
    // through the per-file loop, so the only prompt we expect is for
    // those 5. Verify removed is NOT among them.
    const queriedKinds = spy.promptFileDecisionCalls;
    assert.equal(queriedKinds, 5, "only 5 interactive entries are prompted (removed skipped)");
    assert.equal(seenKinds.includes("removed"), false, "no removed prompts were fired");
    // entries map records the auto-keep decision for documentation/summary.
    assert.equal(result.entries.get("docs/old.md"), "keep");
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  mkdtempSync,
  writeFileSync,
  readFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  unlinkSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname, sep } from "node:path";
import { execSync } from "node:child_process";
import { upgradeCommand } from "../../src/commands/upgrade.js";
import { writeState, readAssetsVersion, readCliVersion } from "../../src/lib/version.js";
import type { Channels } from "../../src/lib/ui.js";
import { resolveAsset } from "../../src/lib/paths.js";
import type { DecisionDeps } from "../../src/upgrade/decision.js";

/**
 * Integration test that exercises the full upgrade pipeline with fake
 * `DecisionDeps`. We construct a synthetic install target tree, write a
 * state.json, then call `upgradeCommand` with the decision deps overridden
 * to drive every decision branch.
 *
 * The test deliberately does NOT depend on a global `tar` invocation
 * beyond what is already required by `createBackup` — if `tar` is missing
 * the relevant assertions skip rather than fail, so the test passes on
 * hosts without tar.
 */

function tarAvailable(): boolean {
  try {
    execSync("tar --version", { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

/** Logged once per test run when tar is missing, so skipped tests are
 * visible in CI output rather than silently passing. */
let tarSkipReasonLogged = false;
function noteTarSkipIfNeeded(): void {
  if (tarSkipReasonLogged) return;
  tarSkipReasonLogged = true;
  // eslint-disable-next-line no-console
  console.log("# skip: tar not available — backup-dependent integration tests");
}

function makeTempTarget(): string {
  return mkdtempSync(join(tmpdir(), "pisquad-upgrade-int-"));
}

/**
 * Populate a fresh target with:
 *   - a valid state.json (so upgradeCommand doesn't bail)
 *   - the assets-version/channels baseline (matching what's currently shipped)
 *
 * Returns the target root. The target's content mirrors what an install
 * created via `pisquad install` would produce, but only for the subtrees
 * we want to test against.
 */
function seedTarget(target: string, channels: Channels): void {
  writeState(target, { channels });
}

interface DecisionLog {
  promptStrategyCalls: number;
  promptFileDecisionCalls: number;
  openEditorCalls: number;
  entriesSeen: Array<{ relPath: string; kind: string }>;
}

function makeDeps(
  strategyAnswer: "all-adopt" | "all-keep" | "per-file" = "per-file",
  answers: Array<{ match: string; answer: "adopt" | "keep" | "edit" }> = [],
  edits: Map<string, string> = new Map(),
): { deps: DecisionDeps; log: DecisionLog } {
  const log: DecisionLog = {
    promptStrategyCalls: 0,
    promptFileDecisionCalls: 0,
    openEditorCalls: 0,
    entriesSeen: [],
  };
  const deps: DecisionDeps = {
    promptStrategy: async () => {
      log.promptStrategyCalls += 1;
      return strategyAnswer;
    },
    promptFileDecision: async (entry, remaining, kind) => {
      log.promptFileDecisionCalls += 1;
      log.entriesSeen.push({ relPath: entry.relPath, kind });
      void remaining;
      void kind;
      // Find the first rule whose `match` substring appears in the relPath;
      // fall through to "keep" if nothing matches (matches the existing
      // semantics for an empty/unmatched answers list).
      for (const rule of answers) {
        if (entry.relPath.includes(rule.match)) return rule.answer;
      }
      return "keep";
    },
    openEditor: async (relPath, _current, _new) => {
      log.openEditorCalls += 1;
      return edits.get(relPath) ?? `edited-${relPath}`;
    },
    sha256Content: (content: string) => {
      // Simple stable hash so matchesTheirs works deterministically.
      let h = 0;
      for (let k = 0; k < content.length; k++) h = ((h << 5) - h + content.charCodeAt(k)) | 0;
      return h.toString(16);
    },
  };
  return { deps, log };
}

/**
 * Touch a file at target/relPath by reading from the assets root (or
 * returning a literal if no assets content is available). Useful to set
 * up "user-modified" content that differs from assets.
 */
function writeUserFile(target: string, relPath: string, content: string): void {
  const abs = join(target, relPath);
  mkdirSync(dirname(abs), { recursive: true });
  writeFileSync(abs, content, "utf-8");
}

function readTarget(target: string, relPath: string): string {
  return readFileSync(join(target, relPath), "utf-8");
}

function assetsRead(relPath: string): string {
  return readFileSync(resolveAsset(relPath), "utf-8");
}

describe("upgradeCommand integration", () => {
  it("interactive edit writes user content", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    } // skip on hosts without tar
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);
    // Seed the target with a user-modified version of an interactive file.
    // We modify docs/README.md so it differs from the assets version.
    const userContent = "# user-modified content\n\nThis is the user's own edits.\n";
    writeUserFile(target, "docs/README.md", userContent);
    // Also pre-create docs/conventions (matching assets layout — so the diff
    // recognises the target as a pisquad install).
    writeUserFile(target, "docs/conventions/install-state.md", "(irrelevant)");
    writeUserFile(target, ".pi/agents/worker.md", "(irrelevant)");

    const editedContent = "user merged content here";
    const edits = new Map([["docs/README.md", editedContent]]);
    const { deps, log } = makeDeps("per-file", [{ match: "docs/README.md", answer: "edit" }], edits);

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactiveSetByUser: true,
        // Force interactive by passing interactive=true (so shouldPrompt returns true).
        interactive: true,
        forceInteractiveEnv: true,
        // Bypass selfUpdate stage via env var; ignore any error from npm view.
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // The user's edited content must be on disk after upgrade.
    const finalContent = readTarget(target, "docs/README.md");
    assert.equal(finalContent, editedContent, "edited content wins");

    // Decision layer was actually invoked once.
    assert.equal(log.promptStrategyCalls, 1);
    assert.equal(log.openEditorCalls >= 1, true, "editor opened at least once");

    // Cleanup
    try {
      execSync(`rm -rf ${target}`, { stdio: "ignore" });
    } catch {
      /* best-effort */
    }
  });

  it("non-interactive: upgradeCommand adopts everything in interactive areas too (legacy behaviour)", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Seed the target with user-modified content for an interactive file.
    const userContent = "USER_EDIT_" + Date.now();
    writeUserFile(target, "docs/README.md", userContent);

    // interactive=false, isInteractiveEnv default false in tests → all-adopt
    const { deps, log } = makeDeps("all-adopt", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactive: false,
        interactiveSetByUser: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // After non-interactive upgrade, docs/README.md must match the assets
    // content (the user's edits were silently overwritten — that's the
    // documented legacy fallback behaviour).
    const finalContent = readTarget(target, "docs/README.md");
    const assetsContent = assetsRead("docs/README.md");
    assert.equal(finalContent, assetsContent, "non-interactive upgraded to assets content");
    assert.equal(log.promptStrategyCalls, 0, "no prompt in non-interactive mode");
  });

  it("managed extension files: always overwritten even in interactive mode", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Pre-create a file under a managed include (`.pi/extensions/subagent`)
    // with user-modified content. Managed includes are NEVER prompted —
    // the decision layer treats them as "always adopt" regardless of
    // strategy. The user's override must be overwritten.
    const targetFile = ".pi/extensions/subagent/index.ts";
    const userContent = "USER_OVERRIDE_" + Date.now();
    writeUserFile(target, targetFile, userContent);

    const { deps } = makeDeps("all-keep", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // The user's override must be gone — managed entries are always
    // overwritten regardless of the strategy the user picked.
    const finalContent = readTarget(target, targetFile);
    assert.equal(
      finalContent.includes("USER_OVERRIDE"),
      false,
      "managed file overwritten even when strategy=all-keep",
    );
    // Sanity check: the file is now the assets' content.
    const assetsContent = assetsRead(targetFile);
    assert.equal(finalContent, assetsContent, "managed file matches assets after upgrade");
  });

  it("prune=true: removed files adopted via all-adopt are deleted", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Create a file in the target that isn't in assets. We'll fabricate
    // an "assets diff" by writing into docs and then deleting it AFTER
    // upgrade computed its plan but BEFORE running. Instead, simulate by
    // simply having target contain a file the assets don't ship and
    // relying on the package diff to detect it as removed.
    //
    // Easier: create a real "removed" scenario by copying an asset, then
    // deleting it before upgrade.
    const targetOnlyRel = "docs/legacy-note.md";
    writeUserFile(target, targetOnlyRel, "legacy");

    const { deps } = makeDeps("all-adopt", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: true,
        decisionDeps: deps,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // The removed file should be gone from the target after --prune.
    assert.equal(existsSync(join(target, targetOnlyRel)), false, "prune removed the file");
  });

  it("decision layer throws (user cancelled): no backup, exit code 1", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Mark the file we want to keep so we can check it survives.
    const marker = "KEEP_ME_" + Date.now();
    writeUserFile(target, "docs/README.md", marker);

    const throwingDeps: DecisionDeps = {
      promptStrategy: async () => {
        throw new Error("user cancelled via Ctrl-C");
      },
    };

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: throwingDeps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      // restore — but capture
    }

    assert.equal(process.exitCode, 1, "exit code set to 1 on cancellation");

    // User content survived (no writes happened).
    const after = readTarget(target, "docs/README.md");
    assert.equal(after, marker, "user content preserved after cancel");

    // No backup tarball should exist (decision layer threw before backup).
    // Strict assertion: the backups dir must not exist at all, or if it
    // does (e.g. left over from a prior run) it must contain no .tar.gz
    // files. This catches regressions where the backup stage runs before
    // a failing decision layer.
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    if (existsSync(backupDir)) {
      const entries = readdirSync(backupDir);
      const tarballs = entries.filter((f) => f.endsWith(".tar.gz"));
      assert.equal(
        tarballs.length,
        0,
        `no .tar.gz files should exist after cancelled upgrade; found: ${tarballs.join(", ")}`,
      );
    }
    process.exitCode = prevExit;
  });

  it("createBackup fails: exit 1, no changes made to target", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Set up a file that the diff will report as modified and that the
    // decision layer will mark for backup. We then sabotage the backup
    // by deleting the file from disk *between* the decision and the
    // createBackup call. The `promptFileDecision` hook fires after the
    // decision but before the upgrade command proceeds to backup, so
    // it's a convenient place to plant the failure.
    const marker = "KEEP_ME_" + Date.now();
    const targetFile = "docs/README.md";
    writeUserFile(target, targetFile, marker);

    const sabotagingDeps: DecisionDeps = {
      promptStrategy: async () => "per-file",
      promptFileDecision: async (_entry, _remaining, _kind) => {
        // Strip the file from disk AFTER the decision has already
        // recorded it for backup. createBackup validates every file
        // exists and will throw — the upgrade must catch that and exit
        // cleanly without touching anything else. Only sabotage once so
        // subsequent promptFileDecision calls don't trip over the
        // missing file (the editor hook reads from disk too).
        try {
          unlinkSync(join(target, targetFile));
          return "adopt";
        } catch {
          // Already gone — fall through to a safe answer.
          return "keep";
        }
      },
      openEditor: async () => "edited-fallback",
    };

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: sabotagingDeps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      /* restore later */
    }

    assert.equal(process.exitCode, 1, "exit code set to 1 on backup failure");
    // No backup should exist (the createBackup call threw before any
    // tarball was written, and the upgrade must bail before the copy
    // stage).
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    if (existsSync(backupDir)) {
      const entries = readdirSync(backupDir);
      const tarballs = entries.filter((f) => f.endsWith(".tar.gz"));
      assert.equal(
        tarballs.length,
        0,
        `no .tar.gz files should exist after backup failure; found: ${tarballs.join(", ")}`,
      );
    }
    process.exitCode = prevExit;
  });

  it("dry-run: shows decision preview summary, never writes backup", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Seed a file so the diff has something to show — we want the
    // decision preview line, not the empty-plan fast path.
    const marker = "USER_CONTENT_" + Date.now();
    writeUserFile(target, "docs/README.md", marker);

    const { deps } = makeDeps("all-keep", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        dryRun: true,
        decisionDeps: deps,
        interactive: false,
        interactiveSetByUser: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // User content survives — dry-run must not touch the target.
    const after = readTarget(target, "docs/README.md");
    assert.equal(after, marker, "user content preserved after dry-run");
    // No backup should exist — dry-run never calls createBackup.
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    assert.equal(existsSync(backupDir), false, "no backups dir created in dry-run");
    // The decision preview must have been printed (via console.log because
    // logger.info is hard to mock from outside the module). node:test
    // captures console output by default; we just assert dry-run
    // completed without throwing and the target is intact.
  });

  it("--interactive with no tty: emits a warning that interactive was ignored", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Seed a file so the diff is non-empty (so the upgrade reaches the
    // decision / apply stages instead of just printing "no changes").
    writeUserFile(target, "docs/README.md", "user");

    const { deps } = makeDeps("all-adopt", []);
    // Capture warn output so we can assert on the W1 message.
    const originalWarn = console.warn;
    const warnings: string[] = [];
    console.warn = (...args: unknown[]) => {
      warnings.push(args.map(String).join(" "));
    };
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        // User explicitly asked for --interactive; we simulate a host
        // with no tty by NOT setting forceInteractiveEnv.
        interactive: true,
        interactiveSetByUser: true,
        noSelf: true,
      });
    } finally {
      console.warn = originalWarn;
      process.exitCode = prevExit;
    }

    const sawWarning = warnings.some((w) => w.includes("--interactive ignored"));
    assert.equal(
      sawWarning,
      true,
      `expected --interactive ignored warning, got: ${warnings.join(" | ")}`,
    );
  });
});

// Quiet node:test import warning
void readAssetsVersion;
void readCliVersion;
void sep;

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { defaultRenderUnifiedDiff } from "../../src/upgrade/decision-defaults.js";

/**
 * `renderUnifiedDiff` must keep working when the system `diff` CLI is
 * absent (CI sandboxes, alpine base images, etc.). We force the fallback by
 * injecting a `which` stub that returns null, and verify the function
 * still returns the new version's content for downstream consumption.
 */
describe("defaultRenderUnifiedDiff", () => {
  it("falls back to readFileSync when diff CLI is missing", async () => {
    const fromAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-from-")), "a.md");
    const toAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-to-")), "b.md");
    const newContent = "new line one\nnew line two\n";
    writeFileSync(fromAbs, "old line one\nold line two\n", "utf-8");
    writeFileSync(toAbs, newContent, "utf-8");

    const result = await defaultRenderUnifiedDiff("docs/example.md", fromAbs, toAbs, {
      which: () => null,
      execCapture: async () => {
        throw new Error("execCapture must not be called when diff is missing");
      },
    });
    assert.equal(result, newContent, "fallback returns the new file's content");
  });

  it("uses diff CLI when available and returns its stdout", async () => {
    const fromAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-from2-")), "a.md");
    const toAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-to2-")), "b.md");
    writeFileSync(fromAbs, "old\n", "utf-8");
    writeFileSync(toAbs, "new\n", "utf-8");

    const fakeDiffOutput = "--- a\n+++ b\n-old\n+new";
    const result = await defaultRenderUnifiedDiff("docs/example.md", fromAbs, toAbs, {
      which: () => "/usr/bin/diff",
      execCapture: async () => ({ stdout: fakeDiffOutput, stderr: "", exitCode: 1 }),
    });
    assert.equal(result, fakeDiffOutput);
  });

  it("returns empty string when diff says files are identical", async () => {
    const tmp = mkdtempSync(join(tmpdir(), "pisquad-diff-same-"));
    const a = join(tmp, "a.md");
    const b = join(tmp, "b.md");
    const content = "same content\n";
    writeFileSync(a, content, "utf-8");
    writeFileSync(b, content, "utf-8");
    const result = await defaultRenderUnifiedDiff("same.md", a, b, {
      which: () => "/usr/bin/diff",
      execCapture: async () => ({ stdout: "", stderr: "", exitCode: 0 }),
    });
    assert.equal(result, "", "identical files → empty stdout");
  });
});

import { copyFileSync, existsSync, rmSync } from "node:fs";
import { execFile } from "node:child_process";
import { dirname, join } from "node:path";
import { promisify } from "node:util";
import { resolveTarget, stateFile, resolveAsset } from "../lib/paths.js";
import { logger } from "../lib/logger.js";
import { diffTree, type PkgInclude, type DiffPlan } from "../lib/diff.js";
import { createBackup } from "../lib/backup.js";
import {
  readAssetsVersion,
  readCliVersion,
  writeState,
  requireState,
  compareVersions,
  StateMissingError,
  type InstallState,
  type ChannelKey,
} from "../lib/version.js";
import { installCodegraph, installEntire } from "../lib/plugins/index.js";
import { copyDir } from "../lib/copy.js";
import { selfUpdate } from "../upgrade/self.js";
import { resolveUpgradeActions, type ResolvedPlan } from "../upgrade/decision.js";
import { buildDefaultDecisionDeps } from "../upgrade/decision-defaults.js";
import { isInteractive } from "../lib/env.js";
import { ensureDir, atomicWriteFile } from "../lib/fs-safe.js";
import { ExitPromptError } from "@inquirer/core";
import type { Channels } from "../lib/ui.js";

const execFileAsync = promisify(execFile);

const NPM_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes — codegraph npm install can be slow
const EXEC_MAX_BUFFER = 64 * 1024 * 1024; // 64MB

export interface UpgradeOptions {
  target?: string;
  /** When true, delete files in target that are no longer in assets. */
  prune?: boolean;
  dryRun?: boolean;
  /** Skip the CLI self-update stage entirely. */
  noSelf?: boolean;
  with?: string;
  without?: string;
  /**
   * Explicit user request for interactive prompts. `true` is set by
   * `--interactive`; `false` by `--no-interactive`; `undefined` means
   * "default" — fall through to the tty + yes-based decision in
   * `upgradeCommand`.
   */
  interactive?: boolean;
  /**
   * True when the user explicitly passed `--interactive` or `--no-interactive`
   * on the command line. Distinguishes "user said no" from "user said
   * nothing, the upgrader defaulted". The decision layer uses this to know
   * whether it should warn when the tty-based fallback runs.
   */
  interactiveSetByUser?: boolean;
  /** Suppress all prompts and accept defaults (existing -y / --yes flag). */
  yes?: boolean;
  /**
   * @internal Test seam — pass fake `DecisionDeps` to drive every decision
   * branch without spawning real prompts or editors. Production code does
   * not set this; `buildDefaultDecisionDeps()` is used instead.
   */
  decisionDeps?: import("../upgrade/decision.js").DecisionDeps;
  /**
   * @internal Test seam — force `isInteractiveEnv` to a specific value
   * regardless of the host tty state. Production code does not set this.
   * Useful for integration tests that want to exercise the interactive
   * code path on CI hosts with no tty.
   */
  forceInteractiveEnv?: boolean;
}

/**
 * `pisquad upgrade` — sync a target install with the assets bundled in this
 * CLI package. See `docs/tasks/pisquad-cli/11-upgrade-command.md` for the full
 * behavioural contract.
 */
export async function upgradeCommand(options: UpgradeOptions): Promise<void> {
  const target = resolveTarget(options.target);
  const dryRun = options.dryRun === true;
  logger.info(`pisquad upgrade → ${target}${dryRun ? " (dry-run)" : ""}`);

  // 1. CLI self-update — if we actually upgraded the global CLI, the in-memory
  //    code is stale; tell the user to re-run and exit cleanly.
  let selfResult;
  try {
    selfResult = await selfUpdate({ logger, noSelf: options.noSelf });
  } catch (error) {
    logger.error(
      `CLI self-update failed: ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exitCode = 1;
    return;
  }
  if (selfResult.updated) {
    logger.success(
      "CLI self-updated to latest. Re-run `pisquad upgrade` to sync this project with the new version.",
    );
    return;
  }

  // 2. Require an existing install — legacy bash-installed projects have no
  //    state.json and must reinstall (PRD non-goal #1).
  let state: InstallState;
  try {
    state = requireState(target);
  } catch (error) {
    if (error instanceof StateMissingError) {
      logger.error(error.message);
      process.exitCode = 1;
      return;
    }
    throw error;
  }

  // 3. Decide the post-upgrade channel set: state baseline + flags.
  let newChannels;
  try {
    newChannels = mergeChannels(state.channels, options);
  } catch (error) {
    logger.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
    return;
  }
  const cliVersion = readCliVersion();
  const assetsVersion = readAssetsVersion();
  const versionDiff = compareVersions(state, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
  });

  // 4. Build the diff include list (subtree granularity, never the whole .pi/).
  //    The includes are intentionally narrow so .pi/assets-version.txt and
  //    .pi/.gitignore (root files) never enter the diff.
  //
  //    `interactive: true` flags user-editable territory (docs, agents,
  //    skills). These are eligible for per-file prompts in
  //    `resolveUpgradeActions`. Extension packages are managed by the
  //    pisquad release process — they are always overwritten, never
  //    presented for per-file adoption.
  const includes: PkgInclude[] = [
    { pkgSubPath: ".pi/agents", targetSubPath: ".pi/agents", interactive: true },
    { pkgSubPath: ".pi/skills", targetSubPath: ".pi/skills", interactive: true },
    {
      pkgSubPath: ".pi/extensions/subagent",
      targetSubPath: ".pi/extensions/subagent",
    },
    {
      pkgSubPath: ".pi/extensions/wikilink-lint",
      targetSubPath: ".pi/extensions/wikilink-lint",
    },
    { pkgSubPath: "docs", targetSubPath: "docs", interactive: true },
  ];
  if (newChannels.codegraph) {
    includes.push({
      pkgSubPath: ".pi/extensions/codegraph",
      targetSubPath: ".pi/extensions/codegraph",
    });
  }
  if (newChannels.entire) {
    includes.push({
      pkgSubPath: ".pi/extensions/entire",
      targetSubPath: ".pi/extensions/entire",
    });
  }

  // 5. Compute the diff plan.
  const plan = await diffTree(target, includes);

  if (versionDiff.versionChanged) {
    logger.info(`assets version: ${state.version} → ${assetsVersion}`);
  }
  if (versionDiff.cliVersionChanged) {
    logger.info(`CLI version: ${state.cliVersion} → ${cliVersion}`);
  }
  if (versionDiff.newChannels.length > 0) {
    logger.info(`new channels: ${versionDiff.newChannels.join(", ")}`);
  }
  if (versionDiff.removedChannels.length > 0) {
    logger.info(`removed channels: ${versionDiff.removedChannels.join(", ")}`);
  }

  // 6. Dry-run: print the plan and stop before any writes. We still run
  //    `resolveUpgradeActions` here (in non-interactive mode) so the user
  //    sees a decision preview alongside the raw plan — counts of how many
  //    files would be adopted, kept, removed, and backed up under the
  //    active flags. `resolveUpgradeActions` is pure (no FS or editor side
  //    effects) so this is safe in dry-run. When the plan is empty we skip
  //    the decision layer entirely; there is nothing to summarise.
  if (dryRun) {
    const planIsEmpty =
      plan.modified.length === 0 && plan.added.length === 0 && plan.removed.length === 0;
    if (!planIsEmpty) {
      // Force non-interactive: no prompts will fire, the all-adopt default
      // applies, and we never call createBackup from this path.
      const dryRunDecision = await resolveUpgradeActions(
        {
          plan,
          includes,
          target,
          prune: options.prune === true,
          interactive: false,
          interactiveSetByUser: true,
          isInteractiveEnv: false,
          yes: true,
        },
        options.decisionDeps ?? buildDefaultDecisionDeps(target, resolveAsset("")),
      );
      const adoptCount = dryRunDecision.adopt.size;
      const keepCount = dryRunDecision.keep.size;
      const editCount = dryRunDecision.editResults.length;
      const backupCount = dryRunDecision.backup.size;
      const removeCount = dryRunDecision.remove.size;
      logger.info(
        `Would adopt: ${adoptCount} / keep: ${keepCount} / edit: ${editCount} / backup: ${backupCount} / remove: ${removeCount}`,
      );
    }
    printPlan(plan, options.prune === true);
    logger.info("DRY RUN — no changes made");
    return;
  }

  // 7. Run the decision layer. Interactive mode requires BOTH:
  //    a. The caller didn't pass `--no-interactive` or `--yes`.
  //    b. The host has a real tty (and is not CI / PISQUAD_NO_TTY).
  //
  //    Without both, we silently fall through to the all-adopt default —
  //    preserving the legacy "no tty → batch overwrite" behaviour. The
  //    decision layer is wrapped in its own try/catch so that a Ctrl-C
  //    inside @inquirer/prompts (an ExitPromptError) leaves the target
  //    untouched and exits with code 1.
  const isInteractiveEnv =
    options.yes !== true &&
    options.interactive !== false &&
    (options.forceInteractiveEnv === true || isInteractive());
  // Heads-up: the user explicitly asked for `--interactive` but we have no
  // tty (or they used `--yes`). Without this warning the command would
  // silently downgrade to batch adopt, which is surprising for someone
  // who reached for the flag. Skip the warning when forceInteractiveEnv
  // is in play (test seam) so CI-driven suites don't see noise.
  if (
    options.forceInteractiveEnv !== true &&
    options.interactiveSetByUser === true &&
    options.interactive === true &&
    !isInteractiveEnv
  ) {
    logger.warn(
      "--interactive ignored: no TTY detected, falling back to non-interactive (adopt-new) mode",
    );
  }
  let decision: ResolvedPlan;
  try {
    decision = await resolveUpgradeActions(
      {
        plan,
        includes,
        target,
        prune: options.prune === true,
        interactive: options.interactive === true,
        interactiveSetByUser: options.interactiveSetByUser === true,
        isInteractiveEnv,
        yes: options.yes === true,
      },
      options.decisionDeps ?? buildDefaultDecisionDeps(target, resolveAsset("")),
    );
  } catch (error) {
    // Distinguish two failure modes: a user-initiated cancellation (Ctrl-C
    // → @inquirer/core's ExitPromptError) is not a fault; surface it
    // honestly. Anything else is a real exception in the decision layer
    // (e.g. diff CLI failure, editor crash, FS error) — call it a failure
    // so the user can debug. Both still leave the target untouched
    // because the decision layer runs before the backup stage.
    const isUserCancel =
      error instanceof ExitPromptError ||
      (error instanceof Error && error.name === "ExitPromptError");
    if (isUserCancel) {
      logger.error("user cancelled — no changes made, no backup created");
    } else {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`upgrade failed during decision: ${message}`);
    }
    process.exitCode = 1;
    return;
  }

  // 8. Back up files the decision layer flagged. Both `adopt` (existing files
  //    that will be overwritten) and `edit` (existing files we will overwrite
  //    post-merge) entries get archived so the user can always recover. We
  //    emit one tarball labelled "before-upgrade" — matching the legacy
  //    command's contract so existing restore tooling keeps working.
  //
  //    Wrapped in try/catch so a missing `tar` binary, full disk, or name
  //    collision produces a clean exit-1 instead of an unhandled rejection.
  //    On backup failure we must not proceed to the copy stage (the user
  //    has no recovery path otherwise) and the target is left untouched.
  const backupSet = decision.backup;
  let backupTarPath: string | null = null;
  if (backupSet.size > 0) {
    try {
      const backupResult = await createBackup(
        target,
        Array.from(backupSet).map((relPath) => ({ relPath })),
        "before-upgrade",
      );
      backupTarPath = backupResult.path;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`backup failed: ${message}`);
      logger.error(
        `no changes were made to ${target}; re-run once the issue is resolved`,
      );
      process.exitCode = 1;
      return;
    }
  }

  // 9-12. Apply changes, prune, run channel-specific work. Wrapped so any
  //       failure is surfaced cleanly with exit code 1 and the backup tarball
  //       left on disk for the user to inspect / restore manually.
  try {
    // 9. Apply modified + added by syncing each include subtree from assets.
    //    copyDir overwrites only files present in src, leaving extra files in
    //    dest alone — so user-added files survive unless --prune handles them
    //    explicitly below.
    //
    //    The filter combines three concerns:
    //    - codegraph subtree skips node_modules and package-lock.json (would
    //      be restored by `npm install` anyway and copying is slow).
    //    - The decision layer's `keep` set is skipped so user-modified
    //      interactive files are NOT overwritten by the recursive copy.
    //    - Files handled by `editResults` are skipped here because step 10
    //      writes the user-merged content over the top of whatever the copy
    //      would have produced.
    for (const inc of includes) {
      const source = resolveAsset(inc.pkgSubPath);
      const destination = join(target, inc.targetSubPath);
      const isCodegraph = inc.pkgSubPath === ".pi/extensions/codegraph";
      copyDir(source, destination, {
        filter: (_abs, rel) => {
          const targetRel = inc.targetSubPath ? `${inc.targetSubPath}/${rel}` : rel;
          if (isCodegraph && (rel === "node_modules" || rel === "package-lock.json")) return false;
          if (decision.keep.has(targetRel)) return false;
          if (decision.editResults.some((e) => e.relPath === targetRel)) return false;
          return true;
        },
        onSkip: (rel, reason) => logger.warn(`Skipped ${rel} (${reason})`),
      });
    }

    // 10. Write back user-edited files. The recursive copy in step 9 staged
    //     the new assets version; we overwrite with the user's edited
    //     content here. Atomic write so a crash mid-write cannot corrupt
    //     the file. `matchesTheirs === true` means the user opened the
    //     editor, saw the new content, and saved it verbatim — i.e. they
    //     effectively chose "Adopt new" via the editor.
    for (const ed of decision.editResults) {
      const abs = join(target, ed.relPath);
      ensureDir(dirname(abs));
      atomicWriteFile(abs, ed.content);
      logger.info(
        `wrote edited ${ed.relPath}${ed.matchesTheirs ? " (matches new version — merged)" : " (user edit kept)"}`,
      );
    }

    // 11. Handle removed files: walk the decision's `remove` set (which only
    //     contains user-confirmed deletions when --prune is in play).
    for (const relPath of decision.remove) {
      const abs = join(target, relPath);
      try {
        rmSync(abs, { force: true });
      } catch (error) {
        logger.warn(
          `Failed to prune ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    }

    // 12. Channel-specific handling. codegraph npm install runs only when
    //     the extension payload actually changed AND we adopted/edited
    //     something under .pi/extensions/codegraph/. We consult the
    //     decision layer's sets (not the raw plan) so a "keep my codegraph
    //     override" choice does not trigger a npm install that would clobber
    //     the kept file via package.json's deps update.
    const codegraphNewlyEnabled = newChannels.codegraph && !state.channels.codegraph;
    const entireNewlyEnabled = newChannels.entire && !state.channels.entire;

    if (codegraphNewlyEnabled) {
      // installCodegraph does its own copy + npm install + codegraph init.
      // The copy we did in step 9 is redundant but harmless (writes the same
      // content) — we let installCodegraph own the full bootstrap.
      await installCodegraph(target, { logger });
    } else if (newChannels.codegraph) {
      const codegraphTouched =
        Array.from(decision.adopt).some((p) =>
          p.startsWith(".pi/extensions/codegraph/"),
        ) ||
        decision.editResults.some((e) => e.relPath.startsWith(".pi/extensions/codegraph/"));
      if (codegraphTouched) {
        await runNpmInstall(join(target, ".pi", "extensions", "codegraph"));
      }
    }

    if (entireNewlyEnabled) {
      await installEntire(target, { logger });
    }

    // 13. codegraph.json: only copy when the target lacks one. We never
    //     overwrite the user's existing config (respect their customisation).
    //     When codegraph is newly enabled, installCodegraph already handles
    //     this; we only need to run the check for the pre-existing case.
    if (newChannels.codegraph && !codegraphNewlyEnabled) {
      const configDest = join(target, "codegraph.json");
      if (!existsSync(configDest)) {
        const configSource = resolveAsset("codegraph.json");
        if (existsSync(configSource)) {
          copyFileSync(configSource, configDest);
          logger.info(`copied codegraph.json → ${configDest}`);
        }
      } else {
        logger.info("codegraph.json already present, keeping user copy");
      }
    }
  } catch (error) {
    logger.error(`upgrade failed: ${error instanceof Error ? error.message : String(error)}`);
    if (backupSet.size > 0) {
      logger.error(`backup retained on disk under .pi/.pisquad/backups/ for manual restore`);
    }
    process.exitCode = 1;
    return;
  }

  // 14. Persist new state. We always write the latest assets version —
  //     even when the user chose "keep my version" for some files, so
  //     the package-side baseline is still current. Per-user overrides
  //     reappear in the next diff because their hashes differ from the
  //     assets' hashes; the warning at the end reminds the user of that.
  writeState(target, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
    lastUpgradedAt: new Date().toISOString(),
  });

  // 15. Summary.
  const keptInteractive = Array.from(decision.entries.values()).filter(
    (d) => d === "keep",
  ).length;
  printSummary({
    newChannels,
    backupCount: backupSet.size,
    backupPaths: backupTarPath === null ? [] : [backupTarPath],
    removedCount: decision.remove.size,
    pruned: options.prune === true,
    statePath: stateFile(target),
    modifiedCount: plan.modified.length,
    addedCount: plan.added.length,
    adoptedCount: decision.adopt.size,
    keptCount: keptInteractive,
    editedCount: decision.editResults.length,
  });
  if (keptInteractive > 0) {
    logger.warn(
      `kept ${keptInteractive} user modification(s) — they will reappear in next upgrade's diff`,
    );
  }
}

async function runNpmInstall(cwd: string): Promise<void> {
  try {
    await execFileAsync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=warn"], {
      cwd,
      timeout: NPM_TIMEOUT_MS,
      maxBuffer: EXEC_MAX_BUFFER,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`npm install in ${cwd} failed: ${message}`);
  }
}

function printPlan(plan: DiffPlan, prune: boolean): void {
  logger.info(`modified (${plan.modified.length}):`);
  for (const m of plan.modified) logger.info(`  M ${m.relPath}`);
  logger.info(`added (${plan.added.length}):`);
  for (const a of plan.added) logger.info(`  A ${a.relPath}`);
  logger.info(`removed (${plan.removed.length}):`);
  for (const r of plan.removed) logger.info(`  D ${r.relPath}${prune ? " (will delete)" : " (will keep)"}`);
  logger.info(`unchanged (${plan.unchanged.length})`);
  if (prune && plan.removed.length > 0) {
    logger.info(`Pruning will also back up the ${plan.removed.length} removed file(s) before deletion.`);
  }
}

interface Summary {
  newChannels: Channels;
  backupCount: number;
  backupPaths: string[];
  removedCount: number;
  pruned: boolean;
  statePath: string;
  modifiedCount: number;
  addedCount: number;
  /** Number of files whose content was adopted from assets this run. */
  adoptedCount: number;
  /** Number of files the user explicitly chose to keep (interactive + --prune-deleted kept). */
  keptCount: number;
  /** Number of files the user edited in $EDITOR and wrote back. */
  editedCount: number;
}

function printSummary(s: Summary): void {
  const parts = ["core"];
  if (s.newChannels.codegraph) parts.push("codegraph");
  if (s.newChannels.entire) parts.push("entire");
  logger.info(`Channels: ${parts.join(" + ")}`);
  logger.info(`Modified: ${s.modifiedCount}, added: ${s.addedCount}`);
  logger.info(`Adopted: ${s.adoptedCount}, kept: ${s.keptCount}, edited: ${s.editedCount}`);
  if (s.removedCount > 0) {
    if (s.pruned) {
      logger.info(`Removed: ${s.removedCount} (pruned)`);
    } else {
      logger.info(`Removed: ${s.removedCount} (kept — pass --prune to delete)`);
    }
  }
  if (s.backupCount > 0) {
    logger.info(`Backup: ${s.backupCount} file(s) archived`);
    for (const p of s.backupPaths) logger.info(`  ${p}`);
  }
  logger.info(`State: ${s.statePath}`);
  logger.success("upgrade complete");
}

// ---- channel merging ---------------------------------------------------------

function parseChannelList(input: string | undefined): Set<Exclude<ChannelKey, "core">> {
  const out = new Set<Exclude<ChannelKey, "core">>();
  if (!input) return out;
  for (const raw of input.split(",")) {
    const v = raw.trim().toLowerCase();
    if (!v) continue;
    if (v === "codegraph" || v === "entire") out.add(v);
    else if (v !== "core") throw new Error(`Unknown channel: ${v}`);
  }
  return out;
}

/**
 * Merge `--with` / `--without` flags onto the state's existing channel set.
 *
 *   - state.channels is the baseline (no implicit changes).
 *   - `--with X` adds X to the baseline (idempotent).
 *   - `--without X` removes X from the baseline (idempotent).
 *   - `--with` and `--without` are mutually exclusive.
 *
 * `core` is always `true`; the schema pins it. The task spec uses this same
 * merge order so a later `pisquad upgrade --with codegraph` after a core-only
 * install adds the channel without re-prompting.
 */
function mergeChannels(base: Channels, options: { with?: string; without?: string }): Channels {
  const withSet = parseChannelList(options.with);
  const withoutSet = parseChannelList(options.without);
  if (withSet.size > 0 && withoutSet.size > 0) {
    throw new Error("Cannot combine --with and --without");
  }
  const next: Channels = {
    core: true,
    codegraph: base.codegraph,
    entire: base.entire,
  };
  if (withSet.size > 0) {
    for (const k of withSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = true;
  }
  if (withoutSet.size > 0) {
    for (const k of withoutSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = false;
  }
  return next;
}

{
  "name": "@nicklin/pisquad",
  "version": "0.1.1",
  "description": "Install and upgrade the pi-squad development foundation",
  "type": "module",
  "bin": {
    "pisquad": "dist/bin.js"
  },
  "files": [
    "dist",
    "assets",
    "README*.md",
    "LICENSE",
    "pisquad"
